INSERT INTO public.packages (name,slug,category,description,duration_minutes,total_questions,is_free,is_published)
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang manajer PLN menyampaikan presentasi mengenai target kinerja kuartal berikutnya kepada seluruh anggota timnya saat rapat mingguan. Dalam proses komunikasi ini, sang manajer berperan sebagai...','[{"key": "A", "text": "Penerima (Receiver)"}, {"key": "B", "text": "Media"}, {"key": "C", "text": "Pengirim (Sender)"}, {"key": "D", "text": "Umpan Balik (Feedback)"}]'::jsonb,'C','Dalam setiap proses komunikasi, Pengirim atau Sender (juga dikenal sebagai sumber atau komunikator) adalah pihak yang memulai komunikasi. Peran utamanya adalah memiliki ide atau informasi, mengemasnya ke dalam bentuk pesan yang dapat dimengerti (proses encoding), dan mentransmisikannya kepada penerima. Dalam skenario ini, manajer PLN adalah inisiator yang memiliki informasi spesifik (target kinerja) dan menyampaikannya kepada timnya, sehingga ia secara jelas memegang peran sebagai pengirim pesan.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang General Manager PLN Unit Induk Wilayah (UIW) mengeluarkan memo internal kepada seluruh Manajer Unit Pelaksana Pelayanan Pelanggan (UP3) mengenai implementasi prosedur keselamatan kerja baru. Bentuk komunikasi ini adalah...','[{"key": "A", "text": "Komunikasi horizontal"}, {"key": "B", "text": "Komunikasi diagonal"}, {"key": "C", "text": "Komunikasi ke atas (upward communication)"}, {"key": "D", "text": "Komunikasi ke bawah (downward communication)"}]'::jsonb,'D','Komunikasi ke bawah adalah alur informasi formal dalam struktur organisasi yang bergerak dari posisi hierarki yang lebih tinggi ke posisi yang lebih rendah. Dalam kasus ini, General Manager, yang memiliki otoritas lebih tinggi, memberikan instruksi atau kebijakan baru kepada para Manajer di bawahnya. Tujuan dari komunikasi ini adalah untuk mendelegasikan tugas, memberikan arahan, dan memastikan kebijakan tingkat atas diimplementasikan secara efektif di level operasional.','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Model komunikasi yang dijabarkan dengan pertanyaan "Siapa, mengatakan apa, melalui saluran apa, kepada siapa, dengan efek apa?" dikemukakan oleh...','[{"key": "A", "text": "Harold Lasswell"}, {"key": "B", "text": "Wilbur Schramm"}, {"key": "C", "text": "Shannon & Weaver"}, {"key": "D", "text": "Charles Osgood"}]'::jsonb,'A','Model komunikasi yang dirumuskan oleh Harold Lasswell pada tahun 1948 merupakan salah satu kerangka dasar dalam studi komunikasi. Model ini menyederhanakan proses komunikasi menjadi lima komponen pertanyaan kunci: "Siapa?" (pengirim), "Mengatakan Apa?" (pesan), "Melalui Saluran Apa?" (media), "Kepada Siapa?" (penerima), dan "Dengan Efek Apa?" (dampak). Model ini sangat berguna untuk menganalisis tindakan komunikasi secara sistematis.','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang petugas teknis PLN menjelaskan penyebab gangguan listrik kepada pelanggan dengan menggunakan istilah "gangguan fasa" dan "tegangan drop" tanpa penjelasan lebih lanjut, sehingga pelanggan menjadi bingung. Hambatan komunikasi yang terjadi di sini adalah...','[{"key": "A", "text": "Hambatan fisik"}, {"key": "B", "text": "Hambatan semantik"}, {"key": "C", "text": "Hambatan psikologis"}, {"key": "D", "text": "Hambatan personal"}]'::jsonb,'B','Hambatan semantik timbul akibat adanya perbedaan dalam pemaknaan atau penafsiran kata, frasa, atau simbol antara pengirim dan penerima. Penggunaan jargon atau istilah teknis seperti "gangguan fasa" kepada pelanggan awam tanpa disertai penjelasan yang memadai adalah contoh klasik dari hambatan ini. Pesan yang dimaksudkan oleh petugas teknis menjadi tidak efektif karena penerima (pelanggan) tidak memiliki kerangka acuan yang sama untuk memahami istilah tersebut.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Rapat koordinasi mingguan antara Manajer Bagian Perencanaan dan Manajer Bagian Konstruksi Jaringan di sebuah unit PLN merupakan contoh dari alur komunikasi...','[{"key": "A", "text": "Vertikal"}, {"key": "B", "text": "Eksternal"}, {"key": "C", "text": "Horizontal"}, {"key": "D", "text": "Informal"}]'::jsonb,'C','Komunikasi horizontal terjadi antara individu, tim, atau departemen yang berada pada tingkat hierarki yang setara dalam sebuah organisasi. Rapat koordinasi antara dua manajer bagian yang berbeda, seperti Perencanaan dan Konstruksi, bertujuan untuk menyelaraskan pekerjaan, memecahkan masalah bersama, dan berbagi informasi. Alur ini sangat penting untuk memastikan kelancaran proses kerja lintas fungsi tanpa harus melalui jalur vertikal ke atasan.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tanggapan atau respons yang diberikan oleh penerima pesan kepada pengirim, yang berfungsi untuk mengukur efektivitas pesan, disebut...','[{"key": "A", "text": "Encoding"}, {"key": "B", "text": "Decoding"}, {"key": "C", "text": "Umpan balik (feedback)"}, {"key": "D", "text": "Channel"}]'::jsonb,'C','Umpan balik adalah respons atau reaksi yang diberikan oleh penerima setelah menerima dan menafsirkan pesan. Elemen ini sangat vital karena mengubah komunikasi dari proses satu arah menjadi dua arah. Melalui umpan balik, pengirim dapat mengetahui apakah pesannya diterima, dipahami dengan benar, disetujui, atau justru menimbulkan kebingungan, sehingga memungkinkan adanya koreksi atau klarifikasi.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama diadakannya town hall meeting oleh direksi PLN dengan para pegawai dari berbagai level adalah untuk...','[{"key": "A", "text": "Meningkatkan citra direksi di mata pegawai"}, {"key": "B", "text": "Memastikan keselarasan pemahaman visi, misi, dan strategi perusahaan"}, {"key": "C", "text": "Memenuhi formalitas peraturan perusahaan"}, {"key": "D", "text": "Menjalin hubungan informal antar pegawai"}]'::jsonb,'B','Town hall meeting adalah sebuah forum komunikasi internal strategis yang memungkinkan pimpinan puncak untuk berinteraksi langsung dengan karyawan dari berbagai lapisan. Tujuan utamanya adalah untuk menyampaikan pesan-pesan penting secara seragam, memperkuat budaya perusahaan, serta memastikan seluruh karyawan memiliki pemahaman yang sama mengenai arah dan tujuan organisasi, sehingga semua dapat bergerak secara sinergis.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Saat terjadi insiden kebakaran pada salah satu gardu induk yang menyebabkan pemadaman listrik meluas, langkah prioritas yang harus diambil oleh tim Humas PLN adalah...','[{"key": "A", "text": "Menunggu laporan investigasi lengkap selesai dalam beberapa hari"}, {"key": "B", "text": "Mengeluarkan pernyataan awal (holding statement) yang berisi simpati dan komitmen untuk penanganan secepatnya"}, {"key": "C", "text": "Menyalahkan pihak eksternal sebagai penyebab insiden"}, {"key": "D", "text": "Menghitung estimasi kerugian finansial perusahaan"}]'::jsonb,'B','Dalam situasi krisis, kecepatan dan kontrol atas narasi adalah hal yang sangat penting. Mengeluarkan holding statement adalah langkah pertama yang taktis dalam manajemen krisis. Pernyataan ini menunjukkan bahwa perusahaan peduli, mengakui adanya masalah, dan sedang mengambil tindakan, meskipun detail lengkapnya belum tersedia. Ini membantu menenangkan publik, mencegah spekulasi liar, dan memberikan waktu bagi tim untuk mengumpulkan informasi yang akurat.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dokumen resmi yang dibuat oleh Humas PLN dan dikirimkan ke berbagai media untuk menginformasikan tentang peresmian Stasiun Pengisian Kendaraan Listrik Umum (SPKLU) baru adalah...','[{"key": "A", "text": "Media briefing"}, {"key": "B", "text": "Press tour"}, {"key": "C", "text": "Press release (siaran pers)"}, {"key": "D", "text": "Advertorial"}]'::jsonb,'C','Siaran pers adalah alat fundamental dalam praktik Public Relations. Ini merupakan dokumen informasi resmi yang ditulis dalam format jurnalistik dan didistribusikan kepada media dengan harapan media akan memuatnya sebagai berita. Tujuannya adalah untuk mendapatkan publisitas yang luas dan kredibel mengenai suatu acara, produk, atau kebijakan perusahaan seperti peresmian SPKLU baru.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kemampuan juru bicara PLN dalam menghadapi pertanyaan tajam dan provokatif dari wartawan saat konferensi pers disebut...','[{"key": "A", "text": "Media monitoring"}, {"key": "B", "text": "Media handling"}, {"key": "C", "text": "Event organizing"}, {"key": "D", "text": "Lobbying"}]'::jsonb,'B','Media handling adalah keterampilan spesifik dalam Public Relations yang mencakup cara mengelola interaksi dengan jurnalis dan media secara efektif. Ini termasuk mempersiapkan juru bicara, mengantisipasi pertanyaan sulit, merumuskan pesan kunci, dan memastikan bahwa setiap interaksi dengan media (termasuk konferensi pers yang penuh tekanan) dapat menghasilkan pemberitaan yang positif dan akurat bagi perusahaan.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika muncul video hoaks di media sosial yang menuduh PLN melakukan kecurangan pada kWh meter, strategi komunikasi krisis yang paling efektif adalah...','[{"key": "A", "text": "Mengabaikan video tersebut dengan asumsi akan hilang dengan sendirinya"}, {"key": "B", "text": "Secara proaktif membuat konten tandingan (misalnya, video edukasi cara kerja kWh meter) dan menyebarkannya melalui kanal resmi"}, {"key": "C", "text": "Hanya memberikan klarifikasi jika ditanya oleh media besar"}, {"key": "D", "text": "Menuntut penyebar video secara hukum tanpa memberikan penjelasan kepada publik"}]'::jsonb,'B','Dalam menghadapi disinformasi atau hoaks di era digital, sikap pasif atau reaktif seringkali tidak efektif. Strategi komunikasi krisis modern menuntut tindakan proaktif. Membuat konten tandingan yang edukatif, menarik secara visual (seperti video), dan didistribusikan melalui kanal resmi adalah cara yang ampuh untuk merebut kembali narasi, mengklarifikasi fakta, dan menunjukkan transparansi kepada publik.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Program "PLN Mengajar" di mana para pegawai PLN datang ke sekolah-sekolah di daerah terpencil untuk berbagi ilmu merupakan bagian dari fungsi Humas, khususnya...','[{"key": "A", "text": "Government relations"}, {"key": "B", "text": "Investor relations"}, {"key": "C", "text": "Community relations (hubungan komunitas)"}, {"key": "D", "text": "Internal relations"}]'::jsonb,'C','Fungsi Community relations dalam Humas berfokus pada pembangunan dan pemeliharaan hubungan yang positif antara perusahaan dengan masyarakat di sekitar wilayah operasinya. Program "PLN Mengajar" adalah contoh nyata dari investasi sosial yang bertujuan untuk memberikan manfaat langsung kepada komunitas, yang pada gilirannya akan membangun citra positif dan social license to operate bagi perusahaan.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tim Humas PLN secara rutin melacak dan menganalisis semua pemberitaan tentang perusahaan di media online, cetak, dan televisi. Kegiatan ini disebut...','[{"key": "A", "text": "Media placement"}, {"key": "B", "text": "Media buying"}, {"key": "C", "text": "Media monitoring"}, {"key": "D", "text": "Media pitching"}]'::jsonb,'C','Media monitoring adalah kegiatan sistematis untuk melacak, mengumpulkan, dan menganalisis penyebutan nama perusahaan, merek, atau isu-isu terkait di berbagai platform media. Kegiatan ini sangat krusial bagi tim Humas untuk memahami sentimen publik, mengukur keberhasilan kampanye, mengidentifikasi tren, dan mendeteksi potensi isu negatif sebelum berkembang menjadi krisis.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Prinsip utama dalam komunikasi krisis yang bertujuan membangun kembali kepercayaan publik adalah...','[{"key": "A", "text": "Menunda informasi untuk menjaga stabilitas internal"}, {"key": "B", "text": "Cepat, transparan, konsisten, dan empatik"}, {"key": "C", "text": "Menunjuk juru bicara dari level tertinggi, meskipun tidak menguasai teknis"}, {"key": "D", "text": "Berkomunikasi hanya melalui satu saluran media saja"}]'::jsonb,'B','Keempat prinsip ini adalah pilar utama dalam komunikasi krisis yang efektif. Kecepatan dibutuhkan untuk mengendalikan narasi. Transparansi (kejujuran) dibutuhkan untuk membangun kembali kepercayaan. Konsistensi pesan di semua saluran mencegah kebingungan. Sementara empati menunjukkan bahwa perusahaan peduli terhadap pihak-pihak yang terdampak, bukan hanya pada bisnisnya sendiri.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang pelanggan datang ke kantor layanan PLN dengan marah karena merasa tagihan listriknya tidak wajar. Sikap etis yang harus ditunjukkan oleh petugas frontliner adalah...','[{"key": "A", "text": "Meminta pelanggan untuk tidak berteriak atau akan dipersilakan keluar"}, {"key": "B", "text": "Langsung menyatakan bahwa sistem tagihan PLN sudah pasti akurat"}, {"key": "C", "text": "Mendengarkan dengan tenang, menunjukkan empati, dan menawarkan untuk melakukan pengecekan detail tagihan bersama"}, {"key": "D", "text": "Memberikan nomor telepon manajer agar pelanggan bisa mengadu langsung"}]'::jsonb,'C','Etika layanan pelanggan yang superior menempatkan pelanggan sebagai fokus utama. Dalam situasi konflik, sikap defensif atau menyalahkan akan memperburuk keadaan. Pendekatan yang etis dan efektif adalah dengan menunjukkan empati untuk memvalidasi perasaan pelanggan, mendengarkan secara aktif untuk memahami akar masalah, dan bersikap solutif dengan menawarkan bantuan nyata.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam laporan studi kelayakan proyek pembangunan pembangkit listrik, bagian yang menyajikan ringkasan singkat dari seluruh isi laporan untuk para pengambil keputusan disebut...','[{"key": "A", "text": "Pendahuluan"}, {"key": "B", "text": "Lampiran"}, {"key": "C", "text": "Daftar Isi"}, {"key": "D", "text": "Ringkasan Eksekutif (Executive Summary)"}]'::jsonb,'D','Ringkasan eksekutif adalah bagian vital dalam sebuah laporan bisnis panjang. Tujuannya adalah untuk menyajikan intisari dari keseluruhan dokumen—termasuk masalah utama, analisis, kesimpulan, dan rekomendasi—dalam format yang padat. Ini dirancang khusus untuk para eksekutif atau pengambil keputusan yang memiliki waktu terbatas agar mereka dapat memahami poin-poin terpenting tanpa harus membaca laporan secara keseluruhan.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang pegawai PLN di unit pengadaan barang memiliki usaha sampingan sebagai pemasok kabel listrik dan mencoba merekomendasikan perusahaannya sendiri untuk proyek PLN. Situasi ini adalah contoh pelanggaran etika berupa...','[{"key": "A", "text": "Negosiasi"}, {"key": "B", "text": "Konflik kepentingan (conflict of interest)"}, {"key": "C", "text": "Lobi bisnis"}, {"key": "D", "text": "Komunikasi persuasif"}]'::jsonb,'B','Konflik kepentingan adalah situasi etis yang bermasalah di mana kepentingan pribadi seseorang berpotensi memengaruhi atau mengganggu objektivitas dan kewajibannya dalam menjalankan peran profesionalnya. Dalam kasus ini, pegawai tersebut memiliki loyalitas ganda—kepada PLN dan kepada perusahaan pribadinya—yang membuatnya tidak dapat membuat keputusan pengadaan yang sepenuhnya objektif dan adil.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam negosiasi pembebasan lahan untuk pembangunan tapak tower transmisi, PLN memberikan kompensasi yang layak dan fasilitas pemberdayaan masyarakat sekitar, sehingga warga setuju. Hasil negosiasi ini disebut...','[{"key": "A", "text": "Win-lose solution"}, {"key": "B", "text": "Lose-lose solution"}, {"key": "C", "text": "Win-win solution"}, {"key": "D", "text": "Zero-sum game"}]'::jsonb,'C','Hasil negosiasi win-win adalah kondisi ideal di mana semua pihak yang terlibat merasa bahwa kepentingan mereka telah terpenuhi dan mereka mendapatkan hasil yang menguntungkan. Ini berbeda dari kompromi di mana setiap pihak mungkin harus mengorbankan sesuatu. Dalam skenario ini, PLN mendapatkan lahan (menang) dan masyarakat mendapatkan kompensasi serta pemberdayaan (menang).','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menjaga kerahasiaan data pribadi pelanggan, seperti nomor IDPEL dan riwayat pemakaian listrik, merupakan implementasi dari etika profesional dalam aspek...','[{"key": "A", "text": "Akuntabilitas"}, {"key": "B", "text": "Transparansi"}, {"key": "C", "text": "Kerahasiaan (confidentiality)"}, {"key": "D", "text": "Integritas"}]'::jsonb,'C','Kerahasiaan adalah prinsip etika profesional yang mengharuskan seseorang untuk tidak mengungkapkan informasi sensitif yang dipercayakan kepadanya dalam konteks hubungan profesional. Menjaga data pelanggan PLN adalah kewajiban hukum dan etis yang fundamental untuk membangun dan mempertahankan kepercayaan pelanggan terhadap perusahaan.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Saat menulis surat elektronik (email) kepada vendor atau mitra kerja, bagian yang wajib dicantumkan setelah isi pesan untuk menunjukkan identitas profesional pengirim adalah...','[{"key": "A", "text": "Tanda tangan digital (digital signature) dan informasi kontak"}, {"key": "B", "text": "Kutipan motivasi"}, {"key": "C", "text": "Alamat media sosial pribadi"}, {"key": "D", "text": "Foto diri informal"}]'::jsonb,'A','Tanda tangan email profesional (bukan tanda tangan kriptografis) adalah blok teks di akhir email yang berfungsi sebagai kartu nama digital. Mencantumkan nama lengkap, jabatan, nama perusahaan, dan informasi kontak yang relevan adalah standar etiket komunikasi bisnis yang menunjukkan profesionalisme, kredibilitas, dan memudahkan mitra kerja untuk menghubungi kembali.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang manajer PLN menyampaikan presentasi mengenai target kinerja kuartal berikutnya kepada seluruh anggota timnya saat rapat mingguan. Dalam proses komunikasi ini, sang manajer berperan sebagai...','[{"key": "A", "text": "Penerima (Receiver)"}, {"key": "B", "text": "Media"}, {"key": "C", "text": "Pengirim (Sender)"}, {"key": "D", "text": "Umpan Balik (Feedback)"}]'::jsonb,'C','Dalam setiap proses komunikasi, Pengirim atau Sender (juga dikenal sebagai sumber atau komunikator) adalah pihak yang memulai komunikasi. Peran utamanya adalah memiliki ide atau informasi, mengemasnya ke dalam bentuk pesan yang dapat dimengerti (proses encoding), dan mentransmisikannya kepada penerima. Dalam skenario ini, manajer PLN adalah inisiator yang memiliki informasi spesifik (target kinerja) dan menyampaikannya kepada timnya, sehingga ia secara jelas memegang peran sebagai pengirim pesan.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang General Manager PLN Unit Induk Wilayah (UIW) mengeluarkan memo internal kepada seluruh Manajer Unit Pelaksana Pelayanan Pelanggan (UP3) mengenai implementasi prosedur keselamatan kerja baru. Bentuk komunikasi ini adalah...','[{"key": "A", "text": "Komunikasi horizontal"}, {"key": "B", "text": "Komunikasi diagonal"}, {"key": "C", "text": "Komunikasi ke atas (upward communication)"}, {"key": "D", "text": "Komunikasi ke bawah (downward communication)"}]'::jsonb,'D','Komunikasi ke bawah adalah alur informasi formal dalam struktur organisasi yang bergerak dari posisi hierarki yang lebih tinggi ke posisi yang lebih rendah. Dalam kasus ini, General Manager, yang memiliki otoritas lebih tinggi, memberikan instruksi atau kebijakan baru kepada para Manajer di bawahnya. Tujuan dari komunikasi ini adalah untuk mendelegasikan tugas, memberikan arahan, dan memastikan kebijakan tingkat atas diimplementasikan secara efektif di level operasional.','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Model komunikasi yang dijabarkan dengan pertanyaan "Siapa, mengatakan apa, melalui saluran apa, kepada siapa, dengan efek apa?" dikemukakan oleh...','[{"key": "A", "text": "Harold Lasswell"}, {"key": "B", "text": "Wilbur Schramm"}, {"key": "C", "text": "Shannon & Weaver"}, {"key": "D", "text": "Charles Osgood"}]'::jsonb,'A','Model komunikasi yang dirumuskan oleh Harold Lasswell pada tahun 1948 merupakan salah satu kerangka dasar dalam studi komunikasi. Model ini menyederhanakan proses komunikasi menjadi lima komponen pertanyaan kunci: "Siapa?" (pengirim), "Mengatakan Apa?" (pesan), "Melalui Saluran Apa?" (media), "Kepada Siapa?" (penerima), dan "Dengan Efek Apa?" (dampak). Model ini sangat berguna untuk menganalisis tindakan komunikasi secara sistematis.','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang petugas teknis PLN menjelaskan penyebab gangguan listrik kepada pelanggan dengan menggunakan istilah "gangguan fasa" dan "tegangan drop" tanpa penjelasan lebih lanjut, sehingga pelanggan menjadi bingung. Hambatan komunikasi yang terjadi di sini adalah...','[{"key": "A", "text": "Hambatan fisik"}, {"key": "B", "text": "Hambatan semantik"}, {"key": "C", "text": "Hambatan psikologis"}, {"key": "D", "text": "Hambatan personal"}]'::jsonb,'B','Hambatan semantik timbul akibat adanya perbedaan dalam pemaknaan atau penafsiran kata, frasa, atau simbol antara pengirim dan penerima. Penggunaan jargon atau istilah teknis seperti "gangguan fasa" kepada pelanggan awam tanpa disertai penjelasan yang memadai adalah contoh klasik dari hambatan ini. Pesan yang dimaksudkan oleh petugas teknis menjadi tidak efektif karena penerima (pelanggan) tidak memiliki kerangka acuan yang sama untuk memahami istilah tersebut.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Rapat koordinasi mingguan antara Manajer Bagian Perencanaan dan Manajer Bagian Konstruksi Jaringan di sebuah unit PLN merupakan contoh dari alur komunikasi...','[{"key": "A", "text": "Vertikal"}, {"key": "B", "text": "Eksternal"}, {"key": "C", "text": "Horizontal"}, {"key": "D", "text": "Informal"}]'::jsonb,'C','Komunikasi horizontal terjadi antara individu, tim, atau departemen yang berada pada tingkat hierarki yang setara dalam sebuah organisasi. Rapat koordinasi antara dua manajer bagian yang berbeda, seperti Perencanaan dan Konstruksi, bertujuan untuk menyelaraskan pekerjaan, memecahkan masalah bersama, dan berbagi informasi. Alur ini sangat penting untuk memastikan kelancaran proses kerja lintas fungsi tanpa harus melalui jalur vertikal ke atasan.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tanggapan atau respons yang diberikan oleh penerima pesan kepada pengirim, yang berfungsi untuk mengukur efektivitas pesan, disebut...','[{"key": "A", "text": "Encoding"}, {"key": "B", "text": "Decoding"}, {"key": "C", "text": "Umpan balik (feedback)"}, {"key": "D", "text": "Channel"}]'::jsonb,'C','Umpan balik adalah respons atau reaksi yang diberikan oleh penerima setelah menerima dan menafsirkan pesan. Elemen ini sangat vital karena mengubah komunikasi dari proses satu arah menjadi dua arah. Melalui umpan balik, pengirim dapat mengetahui apakah pesannya diterima, dipahami dengan benar, disetujui, atau justru menimbulkan kebingungan, sehingga memungkinkan adanya koreksi atau klarifikasi.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama diadakannya town hall meeting oleh direksi PLN dengan para pegawai dari berbagai level adalah untuk...','[{"key": "A", "text": "Meningkatkan citra direksi di mata pegawai"}, {"key": "B", "text": "Memastikan keselarasan pemahaman visi, misi, dan strategi perusahaan"}, {"key": "C", "text": "Memenuhi formalitas peraturan perusahaan"}, {"key": "D", "text": "Menjalin hubungan informal antar pegawai"}]'::jsonb,'B','Town hall meeting adalah sebuah forum komunikasi internal strategis yang memungkinkan pimpinan puncak untuk berinteraksi langsung dengan karyawan dari berbagai lapisan. Tujuan utamanya adalah untuk menyampaikan pesan-pesan penting secara seragam, memperkuat budaya perusahaan, serta memastikan seluruh karyawan memiliki pemahaman yang sama mengenai arah dan tujuan organisasi, sehingga semua dapat bergerak secara sinergis.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Saat terjadi insiden kebakaran pada salah satu gardu induk yang menyebabkan pemadaman listrik meluas, langkah prioritas yang harus diambil oleh tim Humas PLN adalah...','[{"key": "A", "text": "Menunggu laporan investigasi lengkap selesai dalam beberapa hari"}, {"key": "B", "text": "Mengeluarkan pernyataan awal (holding statement) yang berisi simpati dan komitmen untuk penanganan secepatnya"}, {"key": "C", "text": "Menyalahkan pihak eksternal sebagai penyebab insiden"}, {"key": "D", "text": "Menghitung estimasi kerugian finansial perusahaan"}]'::jsonb,'B','Dalam situasi krisis, kecepatan dan kontrol atas narasi adalah hal yang sangat penting. Mengeluarkan holding statement adalah langkah pertama yang taktis dalam manajemen krisis. Pernyataan ini menunjukkan bahwa perusahaan peduli, mengakui adanya masalah, dan sedang mengambil tindakan, meskipun detail lengkapnya belum tersedia. Ini membantu menenangkan publik, mencegah spekulasi liar, dan memberikan waktu bagi tim untuk mengumpulkan informasi yang akurat.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dokumen resmi yang dibuat oleh Humas PLN dan dikirimkan ke berbagai media untuk menginformasikan tentang peresmian Stasiun Pengisian Kendaraan Listrik Umum (SPKLU) baru adalah...','[{"key": "A", "text": "Media briefing"}, {"key": "B", "text": "Press tour"}, {"key": "C", "text": "Press release (siaran pers)"}, {"key": "D", "text": "Advertorial"}]'::jsonb,'C','Siaran pers adalah alat fundamental dalam praktik Public Relations. Ini merupakan dokumen informasi resmi yang ditulis dalam format jurnalistik dan didistribusikan kepada media dengan harapan media akan memuatnya sebagai berita. Tujuannya adalah untuk mendapatkan publisitas yang luas dan kredibel mengenai suatu acara, produk, atau kebijakan perusahaan seperti peresmian SPKLU baru.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kemampuan juru bicara PLN dalam menghadapi pertanyaan tajam dan provokatif dari wartawan saat konferensi pers disebut...','[{"key": "A", "text": "Media monitoring"}, {"key": "B", "text": "Media handling"}, {"key": "C", "text": "Event organizing"}, {"key": "D", "text": "Lobbying"}]'::jsonb,'B','Media handling adalah keterampilan spesifik dalam Public Relations yang mencakup cara mengelola interaksi dengan jurnalis dan media secara efektif. Ini termasuk mempersiapkan juru bicara, mengantisipasi pertanyaan sulit, merumuskan pesan kunci, dan memastikan bahwa setiap interaksi dengan media (termasuk konferensi pers yang penuh tekanan) dapat menghasilkan pemberitaan yang positif dan akurat bagi perusahaan.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika muncul video hoaks di media sosial yang menuduh PLN melakukan kecurangan pada kWh meter, strategi komunikasi krisis yang paling efektif adalah...','[{"key": "A", "text": "Mengabaikan video tersebut dengan asumsi akan hilang dengan sendirinya"}, {"key": "B", "text": "Secara proaktif membuat konten tandingan (misalnya, video edukasi cara kerja kWh meter) dan menyebarkannya melalui kanal resmi"}, {"key": "C", "text": "Hanya memberikan klarifikasi jika ditanya oleh media besar"}, {"key": "D", "text": "Menuntut penyebar video secara hukum tanpa memberikan penjelasan kepada publik"}]'::jsonb,'B','Dalam menghadapi disinformasi atau hoaks di era digital, sikap pasif atau reaktif seringkali tidak efektif. Strategi komunikasi krisis modern menuntut tindakan proaktif. Membuat konten tandingan yang edukatif, menarik secara visual (seperti video), dan didistribusikan melalui kanal resmi adalah cara yang ampuh untuk merebut kembali narasi, mengklarifikasi fakta, dan menunjukkan transparansi kepada publik.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Program "PLN Mengajar" di mana para pegawai PLN datang ke sekolah-sekolah di daerah terpencil untuk berbagi ilmu merupakan bagian dari fungsi Humas, khususnya...','[{"key": "A", "text": "Government relations"}, {"key": "B", "text": "Investor relations"}, {"key": "C", "text": "Community relations (hubungan komunitas)"}, {"key": "D", "text": "Internal relations"}]'::jsonb,'C','Fungsi Community relations dalam Humas berfokus pada pembangunan dan pemeliharaan hubungan yang positif antara perusahaan dengan masyarakat di sekitar wilayah operasinya. Program "PLN Mengajar" adalah contoh nyata dari investasi sosial yang bertujuan untuk memberikan manfaat langsung kepada komunitas, yang pada gilirannya akan membangun citra positif dan social license to operate bagi perusahaan.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tim Humas PLN secara rutin melacak dan menganalisis semua pemberitaan tentang perusahaan di media online, cetak, dan televisi. Kegiatan ini disebut...','[{"key": "A", "text": "Media placement"}, {"key": "B", "text": "Media buying"}, {"key": "C", "text": "Media monitoring"}, {"key": "D", "text": "Media pitching"}]'::jsonb,'C','Media monitoring adalah kegiatan sistematis untuk melacak, mengumpulkan, dan menganalisis penyebutan nama perusahaan, merek, atau isu-isu terkait di berbagai platform media. Kegiatan ini sangat krusial bagi tim Humas untuk memahami sentimen publik, mengukur keberhasilan kampanye, mengidentifikasi tren, dan mendeteksi potensi isu negatif sebelum berkembang menjadi krisis.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Prinsip utama dalam komunikasi krisis yang bertujuan membangun kembali kepercayaan publik adalah...','[{"key": "A", "text": "Menunda informasi untuk menjaga stabilitas internal"}, {"key": "B", "text": "Cepat, transparan, konsisten, dan empatik"}, {"key": "C", "text": "Menunjuk juru bicara dari level tertinggi, meskipun tidak menguasai teknis"}, {"key": "D", "text": "Berkomunikasi hanya melalui satu saluran media saja"}]'::jsonb,'B','Keempat prinsip ini adalah pilar utama dalam komunikasi krisis yang efektif. Kecepatan dibutuhkan untuk mengendalikan narasi. Transparansi (kejujuran) dibutuhkan untuk membangun kembali kepercayaan. Konsistensi pesan di semua saluran mencegah kebingungan. Sementara empati menunjukkan bahwa perusahaan peduli terhadap pihak-pihak yang terdampak, bukan hanya pada bisnisnya sendiri.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang pelanggan datang ke kantor layanan PLN dengan marah karena merasa tagihan listriknya tidak wajar. Sikap etis yang harus ditunjukkan oleh petugas frontliner adalah...','[{"key": "A", "text": "Meminta pelanggan untuk tidak berteriak atau akan dipersilakan keluar"}, {"key": "B", "text": "Langsung menyatakan bahwa sistem tagihan PLN sudah pasti akurat"}, {"key": "C", "text": "Mendengarkan dengan tenang, menunjukkan empati, dan menawarkan untuk melakukan pengecekan detail tagihan bersama"}, {"key": "D", "text": "Memberikan nomor telepon manajer agar pelanggan bisa mengadu langsung"}]'::jsonb,'C','Etika layanan pelanggan yang superior menempatkan pelanggan sebagai fokus utama. Dalam situasi konflik, sikap defensif atau menyalahkan akan memperburuk keadaan. Pendekatan yang etis dan efektif adalah dengan menunjukkan empati untuk memvalidasi perasaan pelanggan, mendengarkan secara aktif untuk memahami akar masalah, dan bersikap solutif dengan menawarkan bantuan nyata.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam laporan studi kelayakan proyek pembangunan pembangkit listrik, bagian yang menyajikan ringkasan singkat dari seluruh isi laporan untuk para pengambil keputusan disebut...','[{"key": "A", "text": "Pendahuluan"}, {"key": "B", "text": "Lampiran"}, {"key": "C", "text": "Daftar Isi"}, {"key": "D", "text": "Ringkasan Eksekutif (Executive Summary)"}]'::jsonb,'D','Ringkasan eksekutif adalah bagian vital dalam sebuah laporan bisnis panjang. Tujuannya adalah untuk menyajikan intisari dari keseluruhan dokumen—termasuk masalah utama, analisis, kesimpulan, dan rekomendasi—dalam format yang padat. Ini dirancang khusus untuk para eksekutif atau pengambil keputusan yang memiliki waktu terbatas agar mereka dapat memahami poin-poin terpenting tanpa harus membaca laporan secara keseluruhan.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang pegawai PLN di unit pengadaan barang memiliki usaha sampingan sebagai pemasok kabel listrik dan mencoba merekomendasikan perusahaannya sendiri untuk proyek PLN. Situasi ini adalah contoh pelanggaran etika berupa...','[{"key": "A", "text": "Negosiasi"}, {"key": "B", "text": "Konflik kepentingan (conflict of interest)"}, {"key": "C", "text": "Lobi bisnis"}, {"key": "D", "text": "Komunikasi persuasif"}]'::jsonb,'B','Konflik kepentingan adalah situasi etis yang bermasalah di mana kepentingan pribadi seseorang berpotensi memengaruhi atau mengganggu objektivitas dan kewajibannya dalam menjalankan peran profesionalnya. Dalam kasus ini, pegawai tersebut memiliki loyalitas ganda—kepada PLN dan kepada perusahaan pribadinya—yang membuatnya tidak dapat membuat keputusan pengadaan yang sepenuhnya objektif dan adil.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam negosiasi pembebasan lahan untuk pembangunan tapak tower transmisi, PLN memberikan kompensasi yang layak dan fasilitas pemberdayaan masyarakat sekitar, sehingga warga setuju. Hasil negosiasi ini disebut...','[{"key": "A", "text": "Win-lose solution"}, {"key": "B", "text": "Lose-lose solution"}, {"key": "C", "text": "Win-win solution"}, {"key": "D", "text": "Zero-sum game"}]'::jsonb,'C','Hasil negosiasi win-win adalah kondisi ideal di mana semua pihak yang terlibat merasa bahwa kepentingan mereka telah terpenuhi dan mereka mendapatkan hasil yang menguntungkan. Ini berbeda dari kompromi di mana setiap pihak mungkin harus mengorbankan sesuatu. Dalam skenario ini, PLN mendapatkan lahan (menang) dan masyarakat mendapatkan kompensasi serta pemberdayaan (menang).','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menjaga kerahasiaan data pribadi pelanggan, seperti nomor IDPEL dan riwayat pemakaian listrik, merupakan implementasi dari etika profesional dalam aspek...','[{"key": "A", "text": "Akuntabilitas"}, {"key": "B", "text": "Transparansi"}, {"key": "C", "text": "Kerahasiaan (confidentiality)"}, {"key": "D", "text": "Integritas"}]'::jsonb,'C','Kerahasiaan adalah prinsip etika profesional yang mengharuskan seseorang untuk tidak mengungkapkan informasi sensitif yang dipercayakan kepadanya dalam konteks hubungan profesional. Menjaga data pelanggan PLN adalah kewajiban hukum dan etis yang fundamental untuk membangun dan mempertahankan kepercayaan pelanggan terhadap perusahaan.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Saat menulis surat elektronik (email) kepada vendor atau mitra kerja, bagian yang wajib dicantumkan setelah isi pesan untuk menunjukkan identitas profesional pengirim adalah...','[{"key": "A", "text": "Tanda tangan digital (digital signature) dan informasi kontak"}, {"key": "B", "text": "Kutipan motivasi"}, {"key": "C", "text": "Alamat media sosial pribadi"}, {"key": "D", "text": "Foto diri informal"}]'::jsonb,'A','Tanda tangan email profesional (bukan tanda tangan kriptografis) adalah blok teks di akhir email yang berfungsi sebagai kartu nama digital. Mencantumkan nama lengkap, jabatan, nama perusahaan, dan informasi kontak yang relevan adalah standar etiket komunikasi bisnis yang menunjukkan profesionalisme, kredibilitas, dan memudahkan mitra kerja untuk menghubungi kembali.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama dari penanganan keluhan pelanggan yang baik dan etis, selain menyelesaikan masalah itu sendiri, adalah...','[{"key": "A", "text": "Memastikan pelanggan tidak akan mengeluh lagi di masa depan"}, {"key": "B", "text": "Menghindari potensi tuntutan hukum"}, {"key": "C", "text": "Memulihkan dan meningkatkan kepercayaan serta loyalitas pelanggan"}, {"key": "D", "text": "Mengurangi beban kerja tim teknis di lapangan"}]'::jsonb,'C','Penanganan keluhan yang efektif memiliki tujuan yang lebih besar dari sekadar menyelesaikan satu masalah. Setiap keluhan adalah kesempatan. Dengan menanganinya secara baik, perusahaan dapat mengubah pengalaman negatif pelanggan menjadi positif. Proses ini tidak hanya memulihkan kepercayaan yang mungkin sempat goyah, tetapi juga dapat memperkuat loyalitas pelanggan dalam jangka panjang.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN akan meluncurkan kampanye nasional tentang penggunaan kompor induksi. Langkah awal yang paling fundamental dalam merancang strategi kampanye tersebut adalah...','[{"key": "A", "text": "Memilih selebriti sebagai duta kampanye"}, {"key": "B", "text": "Menetapkan tujuan yang jelas (misalnya, meningkatkan penjualan kompor induksi) dan mengidentifikasi target audiens"}, {"key": "C", "text": "Mendesain logo dan slogan kampanye"}, {"key": "D", "text": "Memesan slot iklan di stasiun TV nasional"}]'::jsonb,'B','Ini adalah langkah paling fundamental dalam perencanaan strategis. Tanpa tujuan yang jelas (apa yang ingin dicapai?) dan pemahaman mendalam tentang target audiens (siapa yang ingin kita jangkau?), setiap elemen kampanye lainnya—mulai dari pesan, pemilihan media, hingga materi kreatif—tidak akan memiliki arah yang tepat dan berisiko tinggi mengalami kegagalan.','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pesan kunci (key message) untuk kampanye "Hemat Listrik" yang berbunyi, "Cabut Steker, Hemat Biaya, Jaga Bumi," dirancang agar...','[{"key": "A", "text": "Rumit dan memerlukan pemikiran mendalam"}, {"key": "B", "text": "Panjang dan deskriptif"}, {"key": "C", "text": "Singkat, mudah diingat, dan mengandung ajakan bertindak (call to action)"}, {"key": "D", "text": "Hanya dapat dipahami oleh ahli lingkungan"}]'::jsonb,'C','Pesan kunci atau slogan kampanye yang efektif harus dapat dicerna dengan cepat oleh audiens. Sifatnya yang singkat dan ritmis membuatnya mudah diingat. Yang terpenting, pesan tersebut harus secara eksplisit atau implisit mendorong audiens untuk melakukan sesuatu (dalam hal ini, "mencabut steker"), yang merupakan inti dari sebuah call to action.','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Untuk menyosialisasikan kemudahan pembayaran tagihan melalui aplikasi PLN Mobile kepada segmen pelanggan pedesaan, strategi komunikasi yang paling efektif mungkin melibatkan...','[{"key": "A", "text": "Iklan di platform LinkedIn"}, {"key": "B", "text": "Kampanye influencer di TikTok"}, {"key": "C", "text": "Sosialisasi langsung melalui tokoh masyarakat atau aparat desa setempat"}, {"key": "D", "text": "Pemasangan iklan di koran bisnis nasional"}]'::jsonb,'C','Strategi komunikasi harus disesuaikan dengan karakteristik audiens. Untuk segmen pedesaan, di mana penetrasi media digital mungkin tidak merata dan tingkat kepercayaan terhadap figur lokal tinggi, pendekatan komunikasi tatap muka atau melalui perantara tokoh yang dihormati (seperti kepala desa atau tokoh agama) seringkali jauh lebih efektif dan persuasif daripada kampanye media massa.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Identitas visual PLN, seperti penggunaan logo, warna biru yang khas, dan tipografi yang konsisten di semua materi kampanye, bertujuan untuk membangun...','[{"key": "A", "text": "Brand recognition (pengenalan merek) yang kuat"}, {"key": "B", "text": "Anggaran kampanye yang efisien"}, {"key": "C", "text": "Konten yang viral sesaat"}, {"key": "D", "text": "Interaksi dengan audiens"}]'::jsonb,'A','Konsistensi dalam penggunaan elemen identitas visual adalah kunci untuk membangun citra merek yang solid. Ketika publik berulang kali melihat logo, warna, dan gaya visual yang sama di berbagai platform, hal itu akan tertanam dalam ingatan mereka. Ini menciptakan pengenalan merek yang instan dan membedakan PLN dari entitas lain.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan kampanye yang dinyatakan sebagai "Meningkatkan kesadaran masyarakat tentang bahaya bermain layang-layang di dekat jaringan listrik sebesar 30% di wilayah Jawa Barat dalam 6 bulan" adalah contoh tujuan yang...','[{"key": "A", "text": "Terlalu luas dan tidak spesifik"}, {"key": "B", "text": "SMART (Specific, Measurable, Achievable, Relevant, Time-bound)"}, {"key": "C", "text": "Mustahil untuk diukur"}, {"key": "D", "text": "Tidak relevan dengan operasional PLN"}]'::jsonb,'B','Tujuan kampanye ini memenuhi kriteria SMART. Specific: tentang bahaya layang-layang dekat jaringan listrik. Measurable: meningkatkan kesadaran sebesar 30%. Achievable: angka 30% dianggap realistis. Relevant: sangat relevan dengan keselamatan operasional PLN. Time-bound: memiliki batas waktu 6 bulan.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kampanye PLN yang berfokus pada pembangunan Pembangkit Listrik Tenaga Surya (PLTS) dan kontribusinya terhadap pengurangan emisi karbon adalah contoh dari strategi...','[{"key": "A", "text": "Digital branding"}, {"key": "B", "text": "Corporate Social Responsibility (CSR) communication"}, {"key": "C", "text": "Crisis communication"}, {"key": "D", "text": "Internal branding"}]'::jsonb,'B','Komunikasi CSR berfokus pada penyampaian informasi mengenai inisiatif dan kontribusi positif perusahaan terhadap isu-isu sosial dan lingkungan. Mengkomunikasikan pembangunan PLTS dan dampaknya pada pengurangan emisi adalah cara PLN menunjukkan tanggung jawabnya terhadap lingkungan dan pembangunan berkelanjutan, yang merupakan inti dari strategi CSR.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Ketika seorang pelanggan memposting keluhan tentang pemadaman di kolom komentar Instagram resmi PLN, respons terbaik dari admin media sosial adalah...','[{"key": "A", "text": "Menghapus komentar tersebut untuk menjaga citra positif"}, {"key": "B", "text": "Membalas dengan jawaban template tanpa menanyakan detail lebih lanjut"}, {"key": "C", "text": "Menunjukkan empati, meminta maaf atas ketidaknyamanannya, dan meminta ID Pelanggan melalui DM untuk ditindaklanjuti"}, {"key": "D", "text": "Berdebat dengan pelanggan di kolom komentar untuk membuktikan PLN benar"}]'::jsonb,'C','Respons ini adalah praktik terbaik dalam layanan pelanggan digital. Menunjukkan empati dan meminta maaf memvalidasi perasaan pelanggan. Meminta detail melalui Direct Message (DM) memindahkan percakapan yang bersifat personal dan teknis ke ruang privat, sekaligus menunjukkan niat serius untuk menyelesaikan masalah. Ini menjaga citra positif sambil bersikap solutif.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kemampuan media digital yang memungkinkan PLN untuk menargetkan pesan kampanye kompor induksi hanya kepada audiens di kota-kota besar dengan demografi usia 25-45 tahun disebut...','[{"key": "A", "text": "Interaktivitas"}, {"key": "B", "text": "Segmentasi dan penargetan (segmentation & targeting)"}, {"key": "C", "text": "Kecepatan penyebaran"}, {"key": "D", "text": "Aksesibilitas 24/7"}]'::jsonb,'B','Ini adalah salah satu keunggulan terbesar dari media digital. Platform digital memungkinkan pengiklan untuk membagi populasi besar menjadi segmen-segmen yang lebih kecil berdasarkan kriteria spesifik (demografi, geografi, minat, perilaku) dan kemudian menargetkan iklan atau pesan hanya kepada segmen yang paling relevan, sehingga meningkatkan efisiensi dan efektivitas kampanye.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses proaktif memantau percakapan online tentang PLN dan merespons secara strategis untuk membentuk persepsi publik yang positif disebut...','[{"key": "A", "text": "Manajemen konten"}, {"key": "B", "text": "Manajemen reputasi online"}, {"key": "C", "text": "Jurnalisme digital"}, {"key": "D", "text": "Analisis sentimen"}]'::jsonb,'B','Manajemen reputasi online adalah disiplin ilmu yang lebih luas dari sekadar manajemen media sosial. Ini adalah usaha strategis dan berkelanjutan untuk memantau, memengaruhi, dan mengendalikan citra sebuah merek di seluruh ekosistem digital (mesin pencari, situs ulasan, forum, media sosial), dengan tujuan utama membangun dan melindungi persepsi publik yang positif.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Untuk membangun engagement di platform seperti Twitter (X), konten yang paling efektif dari akun PLN adalah...','[{"key": "A", "text": "Salinan siaran pers yang panjang"}, {"key": "B", "text": "Utas (thread) informatif singkat tentang cara membaca meter mandiri, disertai infografis"}, {"key": "C", "text": "Laporan tahunan perusahaan dalam format PDF"}, {"key": "D", "text": "Daftar lengkap nama-nama direksi"}]'::jsonb,'B','Platform seperti Twitter (X) menghargai konten yang ringkas, informatif, dan mudah dibagikan. Utas (thread) memungkinkan penyajian informasi yang sedikit kompleks menjadi bagian-bagian kecil yang mudah dicerna. Penggunaan visual seperti infografis akan meningkatkan daya tarik dan potensi engagement secara signifikan dibandingkan dengan teks panjang atau dokumen formal.','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Ukuran yang menunjukkan seberapa banyak interaksi (suka, komentar, bagikan, simpan) yang diterima oleh sebuah konten di media sosial PLN disebut...','[{"key": "A", "text": "Reach (jangkauan)"}, {"key": "B", "text": "Impressions (tayangan)"}, {"key": "C", "text": "Engagement rate (tingkat keterlibatan)"}, {"key": "D", "text": "Follower growth (pertumbuhan pengikut)"}]'::jsonb,'C','Engagement rate adalah metrik kunci yang mengukur seberapa aktif audiens berinteraksi dengan konten. Metrik ini dihitung berdasarkan jumlah total interaksi (suka, komentar, bagikan, dll.) dibagi dengan jangkauan atau jumlah pengikut. Tingkat keterlibatan yang tinggi umumnya menandakan bahwa konten tersebut relevan dan menarik bagi audiens.','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pengelolaan akun publik PLN yang baik menuntut admin untuk...','[{"key": "A", "text": "Memposting konten kapan saja tanpa jadwal yang terencana"}, {"key": "B", "text": "Memiliki pedoman komunikasi untuk menjaga konsistensi nada dan gaya bahasa"}, {"key": "C", "text": "Menggunakan akun perusahaan untuk me-retweet opini pribadi"}, {"key": "D", "text": "Hanya merespons komentar yang positif saja"}]'::jsonb,'B','Pedoman komunikasi (sering disebut Social Media Style Guide) adalah alat penting untuk memastikan bahwa semua komunikasi yang keluar dari akun resmi perusahaan memiliki suara merek (brand voice) yang konsisten. Ini menjaga profesionalisme dan citra merek, terlepas dari siapa admin yang sedang bertugas.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menghadapi era post-truth di mana hoaks mudah menyebar, fungsi utama kanal komunikasi digital resmi PLN adalah...','[{"key": "A", "text": "Menjadi sumber informasi primer yang terverifikasi dan tepercaya bagi publik"}, {"key": "B", "text": "Ikut menyebarkan berita yang sedang tren untuk meningkatkan engagement"}, {"key": "C", "text": "Tidak mengambil sikap terhadap isu yang beredar"}, {"key": "D", "text": "Menunggu media lain melakukan klarifikasi terlebih dahulu"}]'::jsonb,'A','Di tengah maraknya disinformasi dan hoaks, peran kanal komunikasi resmi perusahaan menjadi semakin vital. Akun resmi harus memposisikan diri sebagai "sumber kebenaran tunggal" (single source of truth) yang dapat diandalkan oleh publik, media, dan pemangku kepentingan lainnya untuk mendapatkan informasi yang akurat dan terverifikasi mengenai perusahaan.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang petugas layanan teknik PLN menolak dengan sopan pemberian uang dari pelanggan setelah memperbaiki instalasi listrik, karena ia memegang teguh prinsip integritas yang merupakan bagian dari nilai BUMN...','[{"key": "A", "text": "Kolaboratif"}, {"key": "B", "text": "Adaptif"}, {"key": "C", "text": "Amanah"}, {"key": "D", "text": "Loyal"}]'::jsonb,'C','Nilai Amanah dalam AKHLAK berarti memegang teguh kepercayaan yang diberikan. Ini tercermin dalam integritas, kejujuran, dan tanggung jawab. Menolak pemberian uang (gratifikasi) adalah wujud nyata dari integritas seorang pegawai yang menjalankan tugasnya secara profesional tanpa mengharapkan imbalan di luar haknya, sehingga ia dapat dipercaya.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tim dari unit transmisi, distribusi, dan pembangkitan bekerja sama erat untuk memulihkan sistem kelistrikan pasca-bencana alam. Sinergi ini adalah cerminan dari nilai...','[{"key": "A", "text": "Kompeten"}, {"key": "B", "text": "Kolaboratif"}, {"key": "C", "text": "Harmonis"}, {"key": "D", "text": "Adaptif"}]'::jsonb,'B','Nilai Kolaboratif menekankan pentingnya membangun kerja sama yang sinergis dan memberikan kesempatan kepada berbagai pihak untuk berkontribusi. Dalam situasi pemulihan pasca-bencana, tidak ada satu unit pun yang bisa bekerja sendiri. Sinergi dan kerja sama erat antar unit yang berbeda adalah kunci keberhasilan, dan ini merupakan perwujudan langsung dari nilai kolaboratif.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menghadapi perubahan teknologi dan tuntutan pelanggan, PLN terus berinovasi dengan mengembangkan fitur smart home yang terintegrasi dengan PLN Mobile. Hal ini menunjukkan penerapan nilai...','[{"key": "A", "text": "Adaptif"}, {"key": "B", "text": "Loyal"}, {"key": "C", "text": "Amanah"}, {"key": "D", "text": "Harmonis"}]'::jsonb,'A','Nilai Adaptif berarti terus berinovasi dan antusias dalam menggerakkan ataupun menghadapi perubahan. Pengembangan fitur smart home yang terintegrasi dengan aplikasi PLN Mobile menunjukkan bahwa PLN tidak statis, melainkan proaktif menyesuaikan diri dengan perkembangan teknologi dan perubahan ekspektasi pelanggan, serta terus mencari cara baru untuk meningkatkan layanannya.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang pegawai PLN yang ditempatkan di daerah terdepan, terluar, dan tertinggal (3T) tetap menjalankan tugasnya dengan penuh dedikasi demi menerangi nusantara. Sikap ini adalah wujud dari nilai...','[{"key": "A", "text": "Kolaboratif"}, {"key": "B", "text": "Adaptif"}, {"key": "C", "text": "Kompeten"}, {"key": "D", "text": "Loyal"}]'::jsonb,'D','Loyalitas dalam konteks BUMN berarti memiliki dedikasi tinggi dan mengutamakan kepentingan Bangsa dan Negara di atas kepentingan pribadi atau kelompok. Sikap pegawai yang tetap berkomitmen menjalankan tugasnya di daerah 3T, meskipun dengan berbagai tantangan, menunjukkan loyalitasnya pada visi besar perusahaan untuk menerangi seluruh negeri dan pada pengabdiannya kepada negara.','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menciptakan lingkungan kerja yang saling peduli dan menghargai perbedaan, serta memberikan layanan yang membantu kepada pelanggan tanpa memandang latar belakang, adalah implementasi dari nilai...','[{"key": "A", "text": "Amanah"}, {"key": "B", "text": "Kompeten"}, {"key": "C", "text": "Harmonis"}, {"key": "D", "text": "Loyal"}]'::jsonb,'C','Nilai Harmonis berfokus pada pentingnya saling peduli dan menghargai perbedaan untuk membangun lingkungan kerja yang kondusif. Sikap ini juga meluas ke layanan eksternal, di mana memberikan layanan yang membantu dan tidak diskriminatif kepada semua pelanggan mencerminkan sikap kepedulian dan keinginan untuk menciptakan hubungan yang baik dengan masyarakat.','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Penerapan nilai AKHLAK secara konsisten dalam setiap komunikasi dan layanan PLN kepada masyarakat pada akhirnya akan bertujuan untuk...','[{"key": "A", "text": "Memenuhi syarat penilaian kinerja dari kementerian"}, {"key": "B", "text": "Membangun kepercayaan publik (public trust) dan reputasi perusahaan yang berkelanjutan"}, {"key": "C", "text": "Mengurangi biaya operasional perusahaan"}, {"key": "D", "text": "Menjadi yang paling populer di antara BUMN lain"}]'::jsonb,'B','Penerapan nilai-nilai luhur seperti AKHLAK bukanlah tujuan akhir itu sendiri, melainkan fondasi. Ketika seluruh insan perusahaan secara konsisten berperilaku amanah, kompeten, harmonis, loyal, adaptif, dan kolaboratif dalam setiap interaksi, hasil akhirnya adalah terbentuknya reputasi yang kokoh dan kepercayaan yang mendalam dari masyarakat, yang sangat penting bagi keberlanjutan perusahaan.','AKDING',40);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang pelanggan membaca brosur dari PLN tentang cara menghemat listrik. Dalam proses ini, pelanggan tersebut berusaha menafsirkan dan memahami pesan yang ada di brosur. Aktivitas yang dilakukan oleh pelanggan ini disebut...','[{"key": "A", "text": "Encoding"}, {"key": "B", "text": "Decoding"}, {"key": "C", "text": "Feedback"}, {"key": "D", "text": "Channel"}]'::jsonb,'B','Decoding adalah proses interpretasi atau pemaknaan yang dilakukan oleh penerima terhadap pesan yang diterimanya. Dalam skenario ini, pelanggan adalah penerima, dan aktivitasnya membaca serta mencoba memahami isi brosur adalah proses decoding simbol-simbol (teks dan gambar) menjadi sebuah gagasan yang berarti.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang staf di Unit Pelaksana Pelayanan Pelanggan (UP3) menyusun laporan bulanan mengenai jumlah keluhan pelanggan dan mengirimkannya kepada Manajer UP3. Alur komunikasi yang terjadi adalah...','[{"key": "A", "text": "Komunikasi ke bawah (downward communication)"}, {"key": "B", "text": "Komunikasi horizontal"}, {"key": "C", "text": "Komunikasi ke atas (upward communication)"}, {"key": "D", "text": "Komunikasi informal"}]'::jsonb,'C','Komunikasi ke atas adalah alur informasi yang bergerak dari level hierarki bawah ke level yang lebih tinggi. Laporan kinerja, umpan balik, atau penyampaian masalah dari staf kepada manajernya adalah contoh klasik dari komunikasi ini, yang penting bagi pimpinan untuk membuat keputusan.','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Media atau sarana yang digunakan untuk menyampaikan pesan dari pengirim kepada penerima, seperti surat edaran, email, atau rapat tatap muka, merupakan elemen komunikasi yang disebut...','[{"key": "A", "text": "Pesan (Message)"}, {"key": "B", "text": "Konteks (Context)"}, {"key": "C", "text": "Saluran (Channel)"}, {"key": "D", "text": "Efek (Effect)"}]'::jsonb,'C','Saluran atau media adalah medium fisik atau non-fisik yang dilalui oleh pesan untuk mencapai penerima. Pemilihan saluran yang tepat sangat memengaruhi efektivitas komunikasi; misalnya, pesan yang kompleks lebih baik disampaikan melalui rapat (saluran kaya) daripada sekadar memo (saluran ringkas).','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Saat rapat evaluasi proyek di sebuah unit PLN, suara bising dari mesin genset di luar ruangan membuat beberapa peserta kesulitan mendengar arahan dari pimpinan rapat. Gangguan semacam ini diklasifikasikan sebagai...','[{"key": "A", "text": "Hambatan semantik"}, {"key": "B", "text": "Hambatan psikologis"}, {"key": "C", "text": "Hambatan personal"}, {"key": "D", "text": "Hambatan fisik"}]'::jsonb,'D','Hambatan fisik adalah gangguan yang berasal dari lingkungan eksternal yang mengganggu transmisi pesan secara fisik. Suara bising dari mesin adalah contoh sempurna yang secara langsung menghalangi proses pendengaran, membuat pesan tidak dapat diterima dengan jelas oleh peserta rapat.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses mengubah ide atau gagasan menjadi simbol-simbol yang dapat dikirimkan, seperti kata-kata, tulisan, atau gambar, yang dilakukan oleh seorang komunikator sebelum mengirim pesan disebut...','[{"key": "A", "text": "Decoding"}, {"key": "B", "text": "Encoding"}, {"key": "C", "text": "Receiving"}, {"key": "D", "text": "Feedback"}]'::jsonb,'B','Encoding adalah proses mental dan kreatif yang dilakukan oleh pengirim untuk mengubah ide atau pemikirannya menjadi format yang dapat ditransmisikan, seperti kata-kata, gestur, atau tulisan. Ini adalah langkah pertama dalam penciptaan sebuah pesan sebelum pesan itu sendiri dikirimkan.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Isu atau gosip yang menyebar cepat dari mulut ke mulut di antara para pegawai di lingkungan kantor PLN mengenai kemungkinan adanya rotasi jabatan adalah contoh dari komunikasi...','[{"key": "A", "text": "Formal"}, {"key": "B", "text": "Vertikal"}, {"key": "C", "text": "Eksternal"}, {"key": "D", "text": "Informal (Grapevine)"}]'::jsonb,'D','Komunikasi informal atau grapevine (selentingan) adalah jaringan komunikasi yang tidak resmi dalam sebuah organisasi. Informasi ini menyebar tidak melalui jalur hierarki formal, melainkan melalui interaksi sosial antar karyawan dan seringkali lebih cepat, meskipun akurasinya tidak selalu terjamin.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang pegawai PLN sedang merenungkan dan mengevaluasi hasil kinerjanya sendiri selama sebulan terakhir. Proses komunikasi yang terjadi di dalam diri individu ini disebut...','[{"key": "A", "text": "Komunikasi interpersonal"}, {"key": "B", "text": "Komunikasi kelompok"}, {"key": "C", "text": "Komunikasi intrapersonal"}, {"key": "D", "text": "Komunikasi publik"}]'::jsonb,'C','Komunikasi intrapersonal adalah proses komunikasi yang terjadi di dalam diri sendiri. Ini melibatkan kegiatan berpikir, merenung, mengevaluasi diri, dan membuat keputusan. Proses ini merupakan dasar bagi setiap bentuk komunikasi lainnya.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tim Humas PLN mengundang sejumlah wartawan dan editor media untuk mengunjungi Pembangkit Listrik Tenaga Air (PLTA) yang baru direvitalisasi untuk menunjukkan teknologi ramah lingkungan secara langsung. Kegiatan ini disebut...','[{"key": "A", "text": "Konferensi Pers (Press Conference)"}, {"key": "B", "text": "Kunjungan Media (Media Visit/Press Tour)"}, {"key": "C", "text": "Wawancara Eksklusif"}, {"key": "D", "text": "Siaran Pers (Press Release)"}]'::jsonb,'B','Media visit adalah kegiatan PR di mana media diundang secara langsung ke lokasi perusahaan untuk mendapatkan pengalaman langsung dan pemahaman mendalam tentang suatu operasi atau produk. Ini lebih efektif daripada siaran pers untuk membangun hubungan dan menghasilkan pemberitaan yang mendalam (liputan khusus).','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kumpulan materi informasi komprehensif tentang PLN (seperti profil perusahaan, data fakta, foto-foto resolusi tinggi, dan rilis pers) yang disiapkan untuk para jurnalis disebut...','[{"key": "A", "text": "Laporan Tahunan"}, {"key": "B", "text": "Media Kit"}, {"key": "C", "text": "Buku Panduan Krisis"}, {"key": "D", "text": "Notulensi Rapat"}]'::jsonb,'B','Media kit adalah seperangkat alat informasi yang dirancang khusus untuk memudahkan pekerjaan jurnalis. Dengan menyediakan semua informasi dasar yang relevan dalam satu paket, perusahaan membantu memastikan bahwa pemberitaan yang dihasilkan akan lebih akurat dan komprehensif.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Persepsi jangka panjang yang terbentuk di benak publik berdasarkan semua tindakan, komunikasi, dan kinerja perusahaan dari waktu ke waktu disebut...','[{"key": "A", "text": "Citra (Image)"}, {"key": "B", "text": "Reputasi (Reputation)"}, {"key": "C", "text": "Publisitas"}, {"key": "D", "text": "Merek (Brand)"}]'::jsonb,'B','Reputasi berbeda dengan citra. Citra bisa dibentuk dalam waktu singkat, namun reputasi dibangun dari akumulasi pengalaman dan kinerja perusahaan dalam jangka panjang. Reputasi yang baik adalah aset tak berwujud yang sangat berharga dan sulit ditiru, terbentuk dari konsistensi antara apa yang dikatakan dan apa yang dilakukan.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Humas PLN secara aktif menjalin hubungan baik dengan pemerintah daerah untuk membahas regulasi terkait pembangunan infrastruktur kelistrikan. Fungsi Humas yang dijalankan dalam hal ini adalah...','[{"key": "A", "text": "Community Relations"}, {"key": "B", "text": "Government Relations"}, {"key": "C", "text": "Media Relations"}, {"key": "D", "text": "Investor Relations"}]'::jsonb,'B','Fungsi ini secara spesifik berfokus pada pembangunan dan pemeliharaan hubungan dengan lembaga-lembaga pemerintahan di semua tingkatan. Tujuannya adalah untuk memengaruhi kebijakan publik, memastikan kepatuhan terhadap regulasi, dan memfasilitasi operasional perusahaan yang terkait dengan izin atau peraturan pemerintah.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Ketika PLN meluncurkan program baru dan secara aktif mengkomunikasikannya kepada publik sebelum ada isu negatif yang muncul, maka pendekatan Humas yang digunakan adalah...','[{"key": "A", "text": "Reaktif"}, {"key": "B", "text": "Pasif"}, {"key": "C", "text": "Proaktif"}, {"key": "D", "text": "Defensif"}]'::jsonb,'C','Humas proaktif berarti mengambil inisiatif untuk membuat program atau mengkomunikasikan pesan sebelum dipaksa oleh keadaan. Dengan meluncurkan kampanye secara terencana, PLN bertindak proaktif untuk membentuk narasi dan persepsi publik, alih-alih menunggu isu negatif muncul lalu meresponsnya (reaktif).','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah surat kabar nasional memuat artikel investigasi yang mengkritik dampak lingkungan dari salah satu proyek pembangkit PLN. Pemberitaan semacam ini, yang muncul tanpa dibayar oleh PLN, merupakan contoh dari...','[{"key": "A", "text": "Paid Media"}, {"key": "B", "text": "Owned Media"}, {"key": "C", "text": "Earned Media"}, {"key": "D", "text": "Shared Media"}]'::jsonb,'C','Earned media adalah publisitas atau liputan yang didapatkan perusahaan secara organik tanpa membayar. Ini bisa berupa artikel berita, ulasan, atau postingan media sosial dari pihak ketiga. Earned media dianggap sangat kredibel karena berasal dari sumber yang independen, meskipun isinya tidak bisa dikontrol oleh perusahaan.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Saat menghadapi krisis, PLN menunjuk satu orang yang memiliki wewenang dan terlatih untuk memberikan semua informasi resmi kepada media. Praktik ini bertujuan untuk...','[{"key": "A", "text": "Menghindari tanggung jawab"}, {"key": "B", "text": "Memperlambat penyebaran informasi"}, {"key": "C", "text": "Menjamin konsistensi dan akurasi pesan"}, {"key": "D", "text": "Menunjukkan kekuatan hierarki perusahaan"}]'::jsonb,'C','Menetapkan satu juru bicara (prinsip satu suara atau one-voice policy) selama krisis adalah praktik standar manajemen krisis. Hal ini mencegah munculnya informasi yang simpang siur atau kontradiktif dari berbagai sumber di dalam perusahaan, sehingga menjaga pesan tetap konsisten, akurat, dan dapat dipercaya oleh publik.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang manajer PLN sedang mendengarkan presentasi dari timnya. Ia tidak hanya mendengar kata-kata, tetapi juga mencoba memahami ide, perasaan, dan pesan di baliknya, sesekali mengangguk dan mengajukan pertanyaan klarifikasi. Praktik ini disebut...','[{"key": "A", "text": "Mendengar pasif"}, {"key": "B", "text": "Mendengar aktif (active listening)"}, {"key": "C", "text": "Mendengar evaluatif"}, {"key": "D", "text": "Mendengar subjektif"}]'::jsonb,'B','Mendengar aktif adalah keterampilan komunikasi yang melampaui sekadar mendengar suara. Ini melibatkan konsentrasi penuh, pemahaman, respons, dan mengingat apa yang dikatakan. Praktik seperti memberikan umpan balik non-verbal (mengangguk) dan mengajukan pertanyaan menunjukkan bahwa manajer benar-benar terlibat dalam proses komunikasi.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam sebuah negosiasi dengan serikat pekerja, manajemen PLN setuju untuk menaikkan tunjangan transportasi, sementara serikat pekerja setuju untuk tidak menuntut kenaikan bonus tahunan. Masing-masing pihak melepaskan sebagian tuntutannya untuk mencapai kesepakatan. Hasil ini adalah contoh dari...','[{"key": "A", "text": "Win-win"}, {"key": "B", "text": "Win-lose"}, {"key": "C", "text": "Kompromi (Compromise)"}, {"key": "D", "text": "Akomodasi"}]'::jsonb,'C','Kompromi adalah hasil negosiasi di mana kedua belah pihak sama-sama mengorbankan sebagian dari tuntutan awal mereka untuk mencapai jalan tengah. Ini berbeda dari win-win di mana kedua pihak mungkin merasa mendapatkan semua yang mereka inginkan; dalam kompromi, ada elemen "memberi dan menerima" yang jelas.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang pegawai di bagian keuangan menemukan adanya ketidakberesan dalam laporan anggaran proyek, namun ia takut melaporkannya karena khawatir akan dimusuhi oleh atasannya yang terlibat. Dilema etis yang dihadapinya berkaitan dengan prinsip...','[{"key": "A", "text": "Loyalitas vs. Kejujuran"}, {"key": "B", "text": "Kerahasiaan vs. Transparansi"}, {"key": "C", "text": "Kepentingan pribadi vs. Profesionalisme"}, {"key": "D", "text": "Keadilan vs. Efisiensi"}]'::jsonb,'A','Ini adalah dilema etis klasik di tempat kerja. Di satu sisi, ada tuntutan untuk loyal kepada atasan atau tim. Di sisi lain, ada kewajiban etis untuk bertindak jujur dan melaporkan kesalahan demi kebaikan perusahaan yang lebih besar. Pegawai tersebut terjebak antara loyalitas personal dan integritas profesional.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Bahasa tubuh seorang negosiator dari PLN yang duduk tegak, menjaga kontak mata, dan menunjukkan ekspresi wajah yang tenang saat bernegosiasi dengan vendor menunjukkan...','[{"key": "A", "text": "Ketidaktertarikan"}, {"key": "B", "text": "Gugup dan cemas"}, {"key": "C", "text": "Rasa percaya diri dan profesionalisme"}, {"key": "D", "text": "Sikap superior dan arogan"}]'::jsonb,'C','Komunikasi non-verbal memainkan peran besar dalam negosiasi. Bahasa tubuh yang terbuka dan terkendali, seperti postur tegak dan kontak mata yang stabil, mengirimkan sinyal kepercayaan diri, keseriusan, dan kredibilitas, yang dapat memperkuat posisi negosiasi seseorang.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah dokumen formal yang disusun oleh tim PLN untuk ditawarkan kepada calon investor, yang berisi analisis pasar, rencana teknis, proyeksi keuangan, dan struktur manajemen proyek pembangkit baru disebut...','[{"key": "A", "text": "Memo internal"}, {"key": "B", "text": "Laporan kegiatan"}, {"key": "C", "text": "Proposal bisnis"}, {"key": "D", "text": "Surat penawaran"}]'::jsonb,'C','Proposal bisnis adalah dokumen persuasif yang dirancang untuk meyakinkan pihak lain (investor, klien, atau mitra) agar menyetujui sebuah proyek atau kerja sama. Isinya harus komprehensif, menguraikan masalah, solusi yang ditawarkan, dan manfaat yang akan diperoleh, didukung oleh data dan analisis yang kuat.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Saat melakukan presentasi bisnis mengenai progres proyek di hadapan direksi, seorang manajer harus memastikan slide presentasinya...','[{"key": "A", "text": "Penuh dengan teks panjang agar informasi lengkap"}, {"key": "B", "text": "Berisi poin-poin kunci yang ringkas dan didukung visual yang jelas"}, {"key": "C", "text": "Menggunakan banyak animasi dan warna yang mencolok untuk menarik perhatian"}, {"key": "D", "text": "Hanya menampilkan data mentah tanpa kesimpulan"}]'::jsonb,'B','Presentasi bisnis yang efektif bukanlah dokumen untuk dibaca, melainkan alat bantu visual. Slide harus berfungsi sebagai penanda visual yang menyoroti poin-poin terpenting, sementara detail penjelasannya disampaikan secara lisan oleh presenter. Terlalu banyak teks akan membuat audiens membaca, bukan mendengarkan.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Prinsip etika komunikasi yang mengharuskan penyampaian informasi secara jujur, akurat, dan tidak menyesatkan kepada publik atau pemangku kepentingan lainnya adalah...','[{"key": "A", "text": "Kerahasiaan"}, {"key": "B", "text": "Objektivitas"}, {"key": "C", "text": "Transparansi"}, {"key": "D", "text": "Empati"}]'::jsonb,'C','Transparansi adalah prinsip etika yang menuntut keterbukaan dan kejujuran dalam komunikasi. Ini berarti tidak menyembunyikan informasi penting yang seharusnya diketahui oleh pemangku kepentingan dan menyajikan data apa adanya, bahkan jika itu kurang menguntungkan, demi membangun kepercayaan jangka panjang.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Setelah kampanye "Aman di Dekat Jaringan Listrik" berjalan selama enam bulan, tim komunikasi PLN melakukan survei untuk mengukur tingkat perubahan pengetahuan dan perilaku masyarakat sasaran. Tahapan kampanye ini disebut...','[{"key": "A", "text": "Perencanaan"}, {"key": "B", "text": "Implementasi"}, {"key": "C", "text": "Evaluasi"}, {"key": "D", "text": "Identifikasi masalah"}]'::jsonb,'C','Evaluasi adalah tahap kritis dalam siklus manajemen kampanye. Pada tahap ini, efektivitas kampanye diukur berdasarkan tujuan yang telah ditetapkan di awal. Hasil evaluasi ini sangat penting untuk mengetahui apa yang berhasil, apa yang tidak, dan menjadi dasar untuk perbaikan kampanye di masa depan.','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kampanye PLN yang bertujuan untuk mengubah kebiasaan masyarakat dari menggunakan listrik pada waktu beban puncak ke waktu di luar beban puncak adalah contoh kampanye yang berfokus pada...','[{"key": "A", "text": "Perubahan kesadaran (awareness)"}, {"key": "B", "text": "Perubahan citra (image)"}, {"key": "C", "text": "Perubahan perilaku (behavior)"}, {"key": "D", "text": "Perubahan opini (opinion)"}]'::jsonb,'C','Tujuan kampanye dapat bervariasi. Dalam kasus ini, tujuan akhirnya bukanlah sekadar agar masyarakat "tahu" tentang waktu beban puncak (kesadaran), tetapi untuk secara aktif "mengubah" kebiasaan mereka dalam menggunakan listrik. Ini adalah tingkat tujuan kampanye yang paling sulit dicapai.','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Untuk meningkatkan kepercayaan publik terhadap program transisi energi, PLN menampilkan video testimoni dari tokoh masyarakat yang telah beralih menggunakan panel surya atap di rumahnya. Penggunaan testimoni ini adalah taktik kampanye yang memanfaatkan prinsip...','[{"key": "A", "text": "Bukti sosial (social proof)"}, {"key": "B", "text": "Otoritas (authority)"}, {"key": "C", "text": "Kelangkaan (scarcity)"}, {"key": "D", "text": "Timbal balik (reciprocity)"}]'::jsonb,'A','Prinsip psikologis bukti sosial menyatakan bahwa orang cenderung mengikuti tindakan orang lain, terutama jika mereka tidak yakin harus berbuat apa. Menampilkan testimoni dari tokoh yang dihormati berfungsi sebagai bukti bahwa orang lain (yang kredibel) telah mengambil tindakan tersebut, sehingga mendorong audiens untuk melakukan hal yang sama.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Slogan kampanye PLN "Listrik untuk Kehidupan yang Lebih Baik" dirancang untuk mengasosiasikan merek PLN dengan manfaat emosional dan fungsional yang positif bagi masyarakat. Fungsi utama slogan dalam hal ini adalah untuk...','[{"key": "A", "text": "Menjelaskan detail teknis produk"}, {"key": "B", "text": "Memposisikan merek (brand positioning)"}, {"key": "C", "text": "Menjadi dasar hukum perusahaan"}, {"key": "D", "text": "Mengatur anggaran kampanye"}]'::jsonb,'B','Slogan adalah alat strategis untuk menanamkan citra atau posisi tertentu di benak konsumen. "Listrik untuk Kehidupan yang Lebih Baik" tidak menjual listrik sebagai komoditas, melainkan memposisikan PLN sebagai penyedia solusi yang meningkatkan kualitas hidup, menciptakan asosiasi merek yang lebih kuat dan emosional.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam merencanakan kampanye, tim Humas PLN menganalisis kekuatan (misalnya, jangkauan luas), kelemahan (misalnya, persepsi tarif mahal), peluang (misalnya, tren kendaraan listrik), dan ancaman (misalnya, hoaks tentang bahaya listrik). Analisis ini dikenal sebagai...','[{"key": "A", "text": "Analisis PEST"}, {"key": "B", "text": "Analisis SMART"}, {"key": "C", "text": "Analisis SWOT"}, {"key": "D", "text": "Analisis AIDA"}]'::jsonb,'C','Analisis SWOT (Strengths, Weaknesses, Opportunities, Threats) adalah kerangka kerja perencanaan strategis yang fundamental. Ini digunakan untuk mengevaluasi faktor internal (Kekuatan, Kelemahan) dan eksternal (Peluang, Ancaman) yang dapat memengaruhi keberhasilan suatu proyek atau kampanye.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Rencana rinci tentang bagaimana sebuah tujuan kampanye akan dicapai disebut sebagai strategi, sedangkan tindakan-tindakan spesifik yang dilakukan untuk menjalankan strategi tersebut (misalnya membuat video, memasang spanduk) disebut...','[{"key": "A", "text": "Visi"}, {"key": "B", "text": "Misi"}, {"key": "C", "text": "Taktik"}, {"key": "D", "text": "Evaluasi"}]'::jsonb,'C','Penting untuk membedakan keduanya. Strategi adalah pendekatan atau rencana besar secara keseluruhan (misalnya, "menggunakan influencer untuk menjangkau generasi muda"). Taktik adalah tindakan spesifik dan konkret untuk melaksanakan strategi tersebut (misalnya, "mengontrak influencer A untuk membuat 3 video TikTok").','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jadwal terstruktur yang merinci kapan dan konten apa yang akan dipublikasikan di setiap akun media sosial PLN (misalnya Instagram, X, Facebook) disebut...','[{"key": "A", "text": "Pedoman Krisis"}, {"key": "B", "text": "Kalender Editorial (Content Calendar)"}, {"key": "C", "text": "Laporan Analitik"}, {"key": "D", "text": "Media Kit Digital"}]'::jsonb,'B','Kalender editorial adalah alat perencanaan yang penting dalam manajemen media sosial. Ini membantu tim untuk merencanakan konten secara terstruktur, memastikan pesan yang konsisten, menghindari postingan yang terburu-buru, dan menyelaraskan konten dengan acara atau kampanye penting.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN bekerja sama dengan seorang influencer otomotif untuk mempromosikan penggunaan Stasiun Pengisian Kendaraan Listrik Umum (SPKLU). Dari perspektif etika digital, hal yang wajib dilakukan oleh influencer adalah...','[{"key": "A", "text": "Menyembunyikan fakta bahwa itu adalah konten berbayar"}, {"key": "B", "text": "Memberikan transparansi kepada audiens bahwa konten tersebut adalah kerja sama promosi (misalnya, dengan tagar #ad atau #sponsored)"}, {"key": "C", "text": "Hanya menyebutkan kelebihan SPKLU dan menutupi semua kekurangannya"}, {"key": "D", "text": "Menggunakan akun pribadinya untuk menyerang produk pesaing"}]'::jsonb,'B','Etika pemasaran influencer dan regulasi di banyak negara mengharuskan adanya pengungkapan (disclosure) yang jelas ketika sebuah konten bersifat komersial. Transparansi ini penting untuk menjaga kepercayaan audiens terhadap influencer dan merek yang bekerja sama.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah metrik dalam analisis media sosial yang mengkategorikan penyebutan merek PLN menjadi positif, negatif, atau netral untuk memahami persepsi publik secara keseluruhan disebut...','[{"key": "A", "text": "Jangkauan (Reach)"}, {"key": "B", "text": "Tingkat Keterlibatan (Engagement Rate)"}, {"key": "C", "text": "Analisis Sentimen"}, {"key": "D", "text": "Pertumbuhan Pengikut"}]'::jsonb,'C','Analisis sentimen adalah proses menggunakan teknologi (seringkali AI) untuk menganalisis teks digital dan mengidentifikasi nada emosional di baliknya. Bagi perusahaan, ini adalah cara cepat untuk mengukur persepsi publik secara agregat dan melacak bagaimana sentimen berubah dari waktu ke waktu.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tantangan utama dalam mengelola komunikasi di platform seperti X (Twitter) adalah sifatnya yang real-time, yang menuntut tim komunikasi PLN untuk...','[{"key": "A", "text": "Hanya aktif pada jam kerja saja"}, {"key": "B", "text": "Merespons isu atau keluhan dengan sangat cepat untuk mencegah eskalasi"}, {"key": "C", "text": "Menunggu persetujuan dari beberapa level manajer sebelum membalas cuitan"}, {"key": "D", "text": "Mengabaikan mention dari akun dengan sedikit pengikut"}]'::jsonb,'B','Sifat percakapan di platform seperti X (Twitter) yang sangat cepat berarti sebuah isu kecil dapat menjadi viral dalam hitungan menit. Oleh karena itu, kecepatan respons (responsivitas) adalah kunci untuk mengendalikan narasi, menunjukkan kepedulian, dan mencegah krisis komunikasi.','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Website resmi PLN (pln.co.id) di mana perusahaan memiliki kontrol penuh atas konten yang dipublikasikan merupakan contoh dari...','[{"key": "A", "text": "Paid Media"}, {"key": "B", "text": "Owned Media"}, {"key": "C", "text": "Earned Media"}, {"key": "D", "text": "Shared Media"}]'::jsonb,'B','Owned media adalah setiap kanal digital yang sepenuhnya dimiliki dan dikendalikan oleh perusahaan. Ini termasuk website korporat, blog, dan akun media sosial resmi. Keuntungannya adalah kontrol penuh atas pesan dan konten.','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Upaya untuk mengoptimalkan konten di website PLN agar muncul di peringkat atas hasil pencarian Google ketika pengguna mencari kata kunci seperti "cara pasang baru listrik" disebut...','[{"key": "A", "text": "Social Media Marketing (SMM)"}, {"key": "B", "text": "Search Engine Optimization (SEO)"}, {"key": "C", "text": "Email Marketing"}, {"key": "D", "text": "Content Management System (CMS)"}]'::jsonb,'B','SEO adalah serangkaian praktik untuk meningkatkan kualitas dan kuantitas lalu lintas ke sebuah situs web melalui hasil pencarian organik (tidak berbayar) di mesin pencari. Tujuannya adalah membuat situs web lebih "terlihat" dan relevan bagi mesin pencari untuk kata kunci tertentu.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah dokumen yang disiapkan oleh tim komunikasi PLN yang berisi prosedur, alur persetujuan, dan pesan kunci yang harus digunakan jika terjadi krisis di media sosial (misalnya, jika tagar negatif tentang PLN menjadi trending) disebut...','[{"key": "A", "text": "Rencana Konten Bulanan"}, {"key": "B", "text": "Rencana Manajemen Krisis Media Sosial"}, {"key": "C", "text": "Panduan Gaya Bahasa Merek"}, {"key": "D", "text": "Laporan Kinerja Media Sosial"}]'::jsonb,'B','Ini adalah dokumen proaktif yang harus dimiliki setiap perusahaan. Rencana ini menguraikan langkah-langkah yang harus diambil, siapa yang bertanggung jawab, dan bagaimana berkomunikasi jika terjadi krisis di media sosial, memastikan respons yang cepat, terkoordinasi, dan efektif.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang teknisi senior PLN secara proaktif meluangkan waktunya untuk mengajari teknisi junior mengenai penggunaan alat baru demi meningkatkan kualitas kerja tim. Sikap ini adalah penerapan dari nilai...','[{"key": "A", "text": "Adaptif"}, {"key": "B", "text": "Loyal"}, {"key": "C", "text": "Kompeten"}, {"key": "D", "text": "Harmonis"}]'::jsonb,'C','Nilai Kompeten berarti terus belajar dan mengembangkan kapabilitas. Sikap teknisi senior yang tidak hanya ahli dalam pekerjaannya tetapi juga aktif berbagi pengetahuan untuk meningkatkan kemampuan timnya adalah perwujudan nyata dari nilai ini. Ia tidak hanya kompeten secara individu, tetapi juga membantu membangun kompetensi organisasi.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang manajer unit layanan PLN secara aktif menengahi dan mencari solusi damai ketika terjadi perselisihan antar dua pegawai di timnya demi menjaga suasana kerja yang positif. Tindakannya mencerminkan nilai...','[{"key": "A", "text": "Kolaboratif"}, {"key": "B", "text": "Harmonis"}, {"key": "C", "text": "Amanah"}, {"key": "D", "text": "Kompeten"}]'::jsonb,'B','Nilai Harmonis menekankan pentingnya kepedulian (caring) dan penghargaan terhadap perbedaan untuk menciptakan lingkungan kerja yang kondusif. Tindakan manajer yang proaktif menjadi penengah dan menjaga keharmonisan tim adalah implementasi langsung dari nilai ini.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang pegawai PLN melaporkan penggunaan kendaraan dinas oleh rekannya untuk kepentingan pribadi di luar jam kerja kepada atasannya melalui jalur yang benar. Tindakan ini merupakan wujud dari nilai...','[{"key": "A", "text": "Adaptif"}, {"key": "B", "text": "Loyal"}, {"key": "C", "text": "Amanah"}, {"key": "D", "text": "Kolaboratif"}]'::jsonb,'C','Amanah berarti dapat dipercaya dan berpegang pada integritas. Melaporkan penyalahgunaan aset perusahaan, meskipun dilakukan oleh rekan kerja, menunjukkan integritas dan tanggung jawab pegawai terhadap kepercayaan yang diberikan kepadanya untuk menjaga aset perusahaan.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tim PLN bekerja sama dengan dinas pekerjaan umum pemerintah daerah untuk menyelaraskan jadwal proyek penggalian kabel bawah tanah agar tidak mengganggu proyek perbaikan jalan. Kerja sama ini adalah contoh nilai...','[{"key": "A", "text": "Kompeten"}, {"key": "B", "text": "Harmonis"}, {"key": "C", "text": "Loyal"}, {"key": "D", "text": "Kolaboratif"}]'::jsonb,'D','Nilai Kolaboratif adalah tentang membangun kerja sama yang sinergis dengan berbagai pihak, baik internal maupun eksternal. Kerja sama PLN dengan pemda menunjukkan kemampuan untuk berkolaborasi dengan pemangku kepentingan lain demi mencapai tujuan bersama dan memberikan hasil yang lebih baik bagi masyarakat.','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Ketika PLN memperkenalkan sistem kerja digital baru, seorang pegawai yang pada awalnya kesulitan, berusaha keras untuk belajar dan dengan cepat menguasai sistem tersebut untuk menunjang pekerjaannya. Ini adalah cerminan dari nilai...','[{"key": "A", "text": "Adaptif"}, {"key": "B", "text": "Amanah"}, {"key": "C", "text": "Harmonis"}, {"key": "D", "text": "Loyal"}]'::jsonb,'A','Nilai Adaptif adalah tentang terus berinovasi dan antusias dalam menghadapi perubahan. Sikap pegawai yang tidak menolak perubahan tetapi justru proaktif belajar dan menyesuaikan diri dengan sistem baru adalah cerminan dari pola pikir yang adaptif dan fleksibel.','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Saat mendengar informasi tidak benar tentang PLN dari lingkungan sekitarnya, seorang pegawai dengan tenang memberikan penjelasan berdasarkan fakta yang ia ketahui untuk menjaga nama baik perusahaan. Sikap ini merupakan wujud dari nilai...','[{"key": "A", "text": "Adaptif"}, {"key": "B", "text": "Kolaboratif"}, {"key": "C", "text": "Loyal"}, {"key": "D", "text": "Kompeten"}]'::jsonb,'C','Loyalitas dalam konteks AKHLAK berarti berdedikasi dan menjaga nama baik sesama karyawan, pimpinan, BUMN, dan Negara. Tindakan pegawai yang secara sadar membela reputasi perusahaan dari informasi yang salah adalah bentuk kontribusi nyata dalam menjaga citra dan nama baik PLN.','AKDING',40);
